      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Apomorphine, an aporphine alkaloid, readily crossed the BBB in rats with brain concentrations exceeding plasma levels, supporting CNS access for N-methylated aporphine-like scaffolds.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Noscapine is predicted to have meaningful CNS access based on its recognized CNS-active phthalideisoquinoline structure and strong transferable evidence from closely related aporphine and protoberberine alkaloids that cross the BBB.",
